package main

import (
	"fmt"
	"strconv"
)

func double(s string) (int, error) {
	v, err := strconv.Atoi(s)
	if err != nil {
		return 0, err // return early on failure
	}
	return v * 2, nil
}

func main() {
	fmt.Println(double("21"))
	fmt.Println(double("x"))
	// Output: 42 <nil>
	// 0 strconv.Atoi: parsing "x": invalid syntax
}

