)

func half(n int) (int, error) {
	if n%2 != 0 {
		return 0, errors.New("n is not even") // failure value
	}
	return n / 2, nil                        // success: nil error
}

func main() {
	if v, err := half(10); err == nil {
		fmt.Println("ok:", v)
	}
	if _, err := half(7); err != nil {
		fmt.Println("error:", err)
	}
}

