type ValidationError struct {
	Field   string
	Message string
}

func (e *ValidationError) Error() string {
	return e.Field + ": " + e.Message // satisfies the error interface
}

func Validate(name string) error {
	if name == "" {
		return fmt.Errorf("validate user: %w",
			&ValidationError{Field: "name", Message: "must not be empty"})
	}
	return nil
}

func handle() {
	err := Validate("")
	var ve *ValidationError
	if errors.As(err, &ve) {            // extract the concrete type from the chain
		fmt.Println("bad field:", ve.Field) // bad field: name
	}
}

var ErrEmpty = errors.New("empty item")

func ProcessAll(items []string, fn func(string) error) error {
	var errs []error
	for _, it := range items {
		if err := fn(it); err != nil {
			// wrap with context, then collect
			errs = append(errs, fmt.Errorf("item %q: %w", it, err))
		}
	}
	return errors.Join(errs...) // nil if errs is empty
}

func main() {
	check := func(s string) error {
		if s == "" {
			return ErrEmpty
		}
		return nil
	}
	err := ProcessAll([]string{"a", "", "b", ""}, check)
	fmt.Println(err != nil)               // true
	fmt.Println(errors.Is(err, ErrEmpty)) // true: Join preserves the chain
}
